mapper.select:
SELECT
recipient_id, senior_id as wardId, bank_code, account_no, holder_name,
send_count, first_sent_at, last_sent_at,
is_registered_safe, safe_registered_at, safe_registered_by, account_alias
FROM recipients
WHERE senior_id = #{wardId}
AND bank_code = #{bankCode}
AND account_no = #{accountNo}
